//! Cross-language parity: the Rust shadow must reproduce the Python golden
//! vectors in `../parity_vectors.tsv` byte-for-byte.
//!
//! Each line is `seed_hex <TAB> id_hex <TAB> expected_key_hex`, generated by the
//! Python prototype. If Python and Rust ever diverge, this test fails.

use neutral_tiebreak::committed_seed_tiebreak_key;

fn from_hex(s: &str) -> Vec<u8> {
    assert!(s.len() % 2 == 0, "odd-length hex: {s}");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("valid hex"))
        .collect()
}

#[test]
fn rust_matches_python_golden_vectors() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../parity_vectors.tsv");
    let data = std::fs::read_to_string(path).expect("read parity_vectors.tsv");
    let mut n = 0;
    for line in data.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split('\t').collect();
        assert_eq!(parts.len(), 3, "expected 3 tab-separated fields: {line}");
        let seed = from_hex(parts[0]);
        let ident = String::from_utf8(from_hex(parts[1])).expect("utf-8 identifier");
        let expected = from_hex(parts[2]);
        let got = committed_seed_tiebreak_key(&seed, &ident).to_vec();
        assert_eq!(got, expected, "Python/Rust mismatch for identifier={ident:?}");
        n += 1;
    }
    assert!(n >= 7, "expected at least 7 parity vectors, got {n}");
}
